      name: 'charge',
      description: 'Create a charge idempotently based on request_id.',
      inputSchema: {
        type: 'object',
        properties: {
          request_id: { type: 'string', description: 'Unique idempotency key for this charge request.' },
          cents: { type: 'integer', description: 'Charge amount in cents; must be a positive integer.' },
        },
        required: ['request_id', 'cents'],
        additionalProperties: false,
      },
    },
  ];
}

function error(code, message) {
  const e = new Error(message);
  e.code = code;
  return e;
}

function isInteger(value) {
  return typeof value === 'number' && Number.isInteger(value);
}

export async function callTool(name, args) {
  if (name !== 'charge') {
    throw error(-32601, `Unknown tool: ${name}`);
  }

  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
    throw error(-32602, 'Invalid arguments: expected an object');
  }

  const allowed = new Set(['request_id', 'cents']);
  for (const key of Object.keys(args)) {
    if (!allowed.has(key)) {
      throw error(-32602, `Unexpected argument: ${key}`);
    }
  }

  if (!('request_id' in args)) {
    throw error(-32602, 'Missing required argument: request_id');
  }
  if (!('cents' in args)) {
    throw error(-32602, 'Missing required argument: cents');
  }

  const { request_id, cents } = args;

  if (typeof request_id !== 'string' || request_id === '') {
    throw error(-32602, 'request_id must be a non-empty string');
  }
  if (!isInteger(cents) || cents <= 0) {
    throw error(-32602, 'cents must be a positive integer');
  }

  // Idempotency: return the stored result for a repeated request_id.
  if (charges.has(request_id)) {
    return charges.get(request_id);
  }

  const chargeId = `ch${charges.size + 1}`;
  const result = {
    content: [{ type: 'text', text: JSON.stringify({ charged: true, charge_id: chargeId }) }],
  };
  charges.set(request_id, result);
  return result;
}
