import { listTools, callTool } from './server.mjs';

const parse = (r) => JSON.parse(r.content[0].text);

// 1. tools/list
console.log('tools/list:', JSON.stringify(await listTools()));

// 2. first charge creates ch1, charged true
const a = parse(await callTool('charge', { request_id: 'r1', cents: 100 }));
console.log('first r1:', JSON.stringify(a));
console.assert(a.charged === true && a.charge_id === 'ch1', 'first charge should be ch1');

// 3. repeated request_id returns same result
const b = parse(await callTool('charge', { request_id: 'r1', cents: 100 }));
console.log('repeat r1:', JSON.stringify(b));
console.assert(JSON.stringify(a) === JSON.stringify(b), 'repeat must equal first');

// 4. different request_id creates separate charge (ch2)
const c = parse(await callTool('charge', { request_id: 'r2', cents: 200 }));
console.log('r2:', JSON.stringify(c));
console.assert(c.charge_id === 'ch2', 'r2 should be ch2');

// 5. count not incremented by repeat (r1 again should still be ch1, not ch3)
const d = parse(await callTool('charge', { request_id: 'r1', cents: 100 }));
console.log('r1 again:', JSON.stringify(d));
console.assert(d.charge_id === 'ch1', 'r1 repeat must stay ch1');

// 6. unknown tool
try { await callTool('foo', {}); console.log('ERROR: unknown tool did not throw'); }
catch (e) { console.log('unknown tool err:', e.message, '(code', e.code + ')'); }

// 7. missing request_id
try { await callTool('charge', { cents: 100 }); console.log('ERROR: missing request_id did not throw'); }
catch (e) { console.log('missing request_id err:', e.message); }

// 8. cents not positive int
try { await callTool('charge', { request_id: 'r3', cents: 0 }); console.log('ERROR: cents=0 did not throw'); }
catch (e) { console.log('cents=0 err:', e.message); }
try { await callTool('charge', { request_id: 'r3', cents: 1.5 }); console.log('ERROR: cents=1.5 did not throw'); }
catch (e) { console.log('cents=1.5 err:', e.message); }

// 9. extra args
try { await callTool('charge', { request_id: 'r4', cents: 100, extra: 1 }); console.log('ERROR: extra arg did not throw'); }
catch (e) { console.log('extra arg err:', e.message); }

console.log('SMOKE DONE');
""}

